def _check_app_live(self, *, require_origin: bool = True) -> None:
        """Check the original issuer and D_app only; never compare broker numbers."""
        s = self._startup
        worker = s.worker
        if (self._closed or _OWNERS.get(worker) is not self
                or threading.get_ident() != s.thread_id or worker.repository is not s.repository
                or worker.active_job_id != s.job_id or worker.visual_role_binding is not s.binding
                or worker._frozen_operational_time_mode != s.mode):
            raise OperationalTimeError("current exact app owner/startup source unavailable")
        if _hash(s.binding.evidence()) != s.binding_hash or _job_source(s.repository.get_job(s.job_id)) != s.job_source:
            raise OperationalTimeError("original app source/policy changed")
        if self._origin_tuple is not None and worker._active_task_origin != self._origin_tuple:
            raise OperationalTimeError("original task origin changed")
        _ = self._clock.domain
        if self._source_hashes is not None:
            pin_worker_source_inventory(self._source_root, self._source_hashes,
                                        required_paths=frozenset(self._source_hashes))
        if require_origin:
            if self.task_origin is None or self.task_origin_token is None or not self._hard:
                raise OperationalTimeError("original app origin unavailable")
            for hard in self._hard:
                current = self._clock.read_current(after=_event_token(self, hard.deadline.origin))
                if not self._clock.before_deadline(hard.deadline, current):
                    raise OperationalTimeError("original app deadline expired")
